message.content:
{
"events": [
{
"key": "bl_shop_boxes",
"intro": "우라하라 상점 앞에 네 갈래 길로 보낼 짐이 쌓여 있다.",
"story": "콘이 끼어든 상자에는 수취인 이름이 가려져 있고, 이치고와 우류가 배송 쪽지를 서로 다르게 읽는다. 오리히메는 사람 없는 뒷길부터 확인하자고 제안한다.",
"choices": [
{"label": "이치고와 앞길을 열고 짐을 옮긴다", "result": "쿠로사키 이치고의 준비를 접었으며, 남은 길에 더 강한 적을 감수하게 된다."},
{"label": "우류와 젖은 배송 쪽지를 복구한다", "result": "이시다 우류의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출된다."},
{"label": "오리히메와 뒷길의 통행을 정리한다", "result": "이노우에 오리히메의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출되고 통로를 정비해 남은 적 수를 줄인다."},
{"label": "콘이 섞인 짐을 찾아 묶음부터 다시 나눈다", "result": "배송 정리 수고비와 보급품을 챙겼으며, 남은 길에 더 많은 적을 감수하게 된다."}
]
},
{
"key": "bl_rooftop_marks",
"intro": "앞길의 짐을 옮긴 뒤, 돌아가는 길 위로 같은 발자국이 이어진다.",
"story": "요루이치는 좁은 발판을 통해 거리를 벌리자고 하고 루키아는 적이 몰리기 전에 골목 입구를 맡자고 한다.",
"choices": [
{"label": "요루이치가 짚은 발판을 정비한다", "result": "시호인 요루이치의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출되고 통로를 정비해 남은 적 수를 줄인다."},
{"label": "루키아와 골목 입구를 맡는다", "result": "쿠치키 루키아의 준비를 접었으며, 남은 길에 더 많은 적을 감수하게 된다."}
]
},
{
"key": "bl_return_receipt",
"intro": "배송 쪽지의 글씨를 되살렸지만 짐을 보내야 할 집까지는 위험한 구간이 남았다.",
"story": "우라하라는 약속한 준비물을 펼치고, 차드는 짐을 한 번에 나눠 들어 좁은 길을 비우려 한다.",
"choices": [
{"label": "우라하라에게 다음 구간의 준비물을 맡긴다", "result": "우라하라 키스케의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출된다."},
{"label": "차드와 짐을 나눠 안전 통로를 만든다", "result": "사도 야스토라의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출되고 통로를 정비해 남은 적 수를 줄인다."}
]
},
{
"key": "bl_closed_lane",
"intro": "오리히메와 사람들을 먼저 보낸 뒷길이 조용해졌다.",
"story": "하지만 바깥 골목의 흔적은 아직 남아 있어 루키아가 그쪽을 맡으려 한다. 차드는 돌아오는 사람이 길을 잃지 않게 표식을 더 세우자고 한다.",
"choices": [
{"label": "루키아와 바깥 골목의 흔적을 따라간다", "result": "쿠치키 루키아의 준비를 접었으며, 남은 길에 더 강한 적을 감수하게 된다."},
{"label": "차드와 귀환 표식을 세운다", "result": "사도 야스토라의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출된다."}
]
},
{
"key": "bl_light_parcel",
"intro": "콘을 잘못 묶인 짐에서 꺼내자 구겨진 배송 메모가 함께 떨어졌다.",
"story": "오리히메는 늦어진 배송을 걱정하고, 우라하라는 목적지별로 꼭 필요한 물품부터 추리자고 한다.",
"choices": [
{"label": "오리히메와 남은 배송 길을 살핀다", "result": "이노우에 오리히메의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출된다."},
{"label": "우라하라와 필요한 물품만 골라 싣는다", "result": "우라하라 키스케의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출된다."}
]
},
{
"key": "bl_stray_alarm",
"intro": "경보가 서로 다른 골목에서 엇갈려 울린다.",
"story": "요루이치는 가장 가까운 신호를 따라 좁은 길로 들어가려 하고, 차드는 사람들이 지나는 길을 먼저 확보한다. 우류는 흩어진 표시를 대조해 잘못된 신호를 가리려 한다.",
"choices": [
{"label": "요루이치와 가까운 신호를 추적한다", "result": "시호인 요루이치의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출되고 남은 길에 더 많은 적을 감수하게 된다. 신호 추적은 실패할 수 있으며 준비 비용과 더 많은 적에 대한 부담이 남는다."},
{"label": "차드와 통행로의 짐을 치운다", "result": "사도 야스토라의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출되고 통로를 정비해 남은 적 수를 줄인다."},
{"label": "우류와 경보 표시를 대조한다", "result": "이시다 우류의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출된다."}
]
},
{
"key": "bl_unmarked_corner",
"intro": "추적했던 경보는 빈 골목에서 끊겼고 쓸 수 있는 표식도 줄었다.",
"story": "루키아는 돌아갈 갈림길을 다시 확인하고, 우라하라는 경보 기록에서 빼먹은 지점을 짚는다.",
"choices": [
{"label": "루키아와 갈림길을 다시 표시한다", "result": "쿠치키 루키아의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출되고 통로를 정비해 남은 적 수를 줄인다."},
{"label": "우라하라에게 경보 기록을 보여 준다", "result": "우라하라 키스케의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출된다."}
]
},
{
"key": "bl_joint_training",
"intro": "이치고와 앞길을 맡아 본 뒤, 칼을 너무 빨리 뻗으면 다음 동작이 흐트러진다는 점을 알게 된다.",
"story": "이치고는 더 강한 상대의 틈을 기다려 한 번에 힘을 모으려 한다. 차드는 길을 넓혀 다음 공격을 버틸 자리를 먼저 고르자고 한다.",
"choices": [
{"label": "이치고와 한 번의 틈에 힘을 모은다", "result": "쿠로사키 이치고의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출되고 남은 길에 더 강한 적을 감수하게 된다."},
{"label": "차드와 버틸 자리를 고른다", "result": "사도 야스토라의 준비를 접었으며, 배송 또는 표식·수련 준비에 비용이 지출되고 통로를 정비해 남은 적 수를 줄인다."}
]
}
]
}
